import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"隱私權選項","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/privacy-choices.md","filePath":"zh-TW/guide/privacy-choices.md","lastUpdated":1793173149000}`),a={name:`zh-TW/guide/privacy-choices.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="隱私權選項" tabindex="-1">隱私權選項 <a class="header-anchor" href="#隱私權選項" aria-label="Permalink to “隱私權選項”">​</a></h1><p>Sudoku 是一款以離線優先為設計原則的 App，資料處理方式極為單純。本頁說明你有哪些隱私選項，以及如何掌控自己的資料。</p><h2 id="你的資料預設留在裝置上" tabindex="-1">你的資料預設留在裝置上 <a class="header-anchor" href="#你的資料預設留在裝置上" aria-label="Permalink to “你的資料預設留在裝置上”">​</a></h2><ul><li>所有遊戲資料——設定、遊戲狀態、鉛筆筆記與統計資料——預設都儲存在你的裝置本機。</li><li>核心玩法完全不需要網路存取。</li><li>沒有廣告、沒有分析工具，也沒有追蹤。</li></ul><h2 id="選用的雲端功能" tabindex="-1">選用的雲端功能 <a class="header-anchor" href="#選用的雲端功能" aria-label="Permalink to “選用的雲端功能”">​</a></h2><h3 id="icloud-同步" tabindex="-1">iCloud 同步 <a class="header-anchor" href="#icloud-同步" aria-label="Permalink to “iCloud 同步”">​</a></h3><p>如果你選擇啟用 iCloud 同步：</p><ul><li>資料只會同步到<strong>你的個人 iCloud 帳號</strong>，不會傳到我們控制的任何伺服器。</li><li>傳輸過程與存放時的加密皆由 Apple 的 CloudKit 處理。</li><li>你隨時可以關閉此功能：設定 →［你的名字］→ iCloud →「使用 iCloud 的 App」→ 將 Sudoku 關閉。</li></ul><h3 id="game-center" tabindex="-1">Game Center <a class="header-anchor" href="#game-center" aria-label="Permalink to “Game Center”">​</a></h3><p>如果你選擇使用 Game Center：</p><ul><li>排行榜分數可能會以你的 Game Center 顯示名稱公開顯示。</li><li>成就進度由 Game Center 記錄。</li><li>你可以在「設定」中登出 Game Center 來停用此功能。</li></ul><h2 id="唯一的非雲端網路功能-「更多-app」" tabindex="-1">唯一的非雲端網路功能：「更多 App」 <a class="header-anchor" href="#唯一的非雲端網路功能-「更多-app」" aria-label="Permalink to “唯一的非雲端網路功能：「更多 App」”">​</a></h2><p>唯一的其他網路存取，是「設定」中選用的<strong>「更多 App」</strong>區塊，會取得一系列相關 App 的清單。此功能：</p><ul><li>不傳送任何個人資料——只會取得 App 名稱與連結的清單。</li><li>可以完全忽略，對遊戲體驗沒有任何影響。</li><li>不會追蹤你，也不會儲存任何識別碼。</li></ul><h2 id="清除你的資料" tabindex="-1">清除你的資料 <a class="header-anchor" href="#清除你的資料" aria-label="Permalink to “清除你的資料”">​</a></h2><p>若要從裝置移除所有 App 資料：</p><ul><li><strong>iPhone/iPad</strong>：刪除並重新安裝 App</li><li><strong>Mac</strong>：結束 Sudoku，然後移除容器：</li></ul><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.sudoku</span></span></code></pre></div><p>若要一併清除 iCloud 中同步的資料：</p><ol><li>前往 <strong>設定 →［你的名字］→ iCloud → 管理帳號儲存空間</strong></li><li>在 App 清單中找到 Sudoku</li><li>點一下 <strong>刪除資料</strong></li></ol><p>這會從 iCloud 永久刪除所有設定、統計資料、遊戲存檔與每日挑戰進度。</p><h2 id="不追蹤、沒有廣告" tabindex="-1">不追蹤、沒有廣告 <a class="header-anchor" href="#不追蹤、沒有廣告" aria-label="Permalink to “不追蹤、沒有廣告”">​</a></h2><p>Sudoku 不含任何廣告、分析工具、追蹤像素或第三方資料分享整合。本 App 遊玩時不需要網路存取。</p><h2 id="隱私權請求一覽" tabindex="-1">隱私權請求一覽 <a class="header-anchor" href="#隱私權請求一覽" aria-label="Permalink to “隱私權請求一覽”">​</a></h2><table tabindex="0"><thead><tr><th>請求</th><th>是否必要</th><th>作用</th></tr></thead><tbody><tr><td>本機儲存</td><td>是（自動）</td><td>將遊戲資料儲存在裝置上</td></tr><tr><td>iCloud 同步</td><td>選用</td><td>透過 CloudKit 在裝置間同步資料</td></tr><tr><td>Game Center</td><td>選用</td><td>排行榜與成就</td></tr><tr><td>網路（「更多 App」）</td><td>選用</td><td>取得相關 App 清單</td></tr></tbody></table><p>由於我們未蒐集任何個人資料，也未將其傳送到我們控制的伺服器，因此並沒有可供存取、刪除或匯出的中央資料庫。所有資料不是在本機，就是由 Apple 的服務（iCloud／Game Center）管理。</p><h2 id="聯絡我們" tabindex="-1">聯絡我們 <a class="header-anchor" href="#聯絡我們" aria-label="Permalink to “聯絡我們”">​</a></h2><p>若你對此流程有任何疑問，請在 <code>https://github.com/sudoku-pro/sudoku-site/issues</code> 提出 issue，或寄信到 <a href="mailto:sudoku@w3cub.com" target="_blank" rel="noreferrer">sudoku@w3cub.com</a>。</p>`,28)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};